-- scripts/restauration/schema-reference.sql — description des TABLES de la base de production au 16/10/2026 (colonnes, séquences, contraintes, index, sécurité par ligne).
-- Sert au test de restauration (scripts/restauration/essai-restauration.js) : il faut bien une base à reconstruire. Généré depuis le catalogue de la production
-- (information_schema / pg_get_constraintdef / pg_indexes), pas écrit à la main. Les FONCTIONS, déclencheurs et règles viennent, eux, des scripts du dossier sql/
-- (que le test rejoue dans l'ordre) : c'est justement ce qui montre si le dépôt suffit à reconstruire la base.
-- À REGÉNÉRER quand une table change (voir LISEZMOI.md). Ne jamais l'appliquer sur la vraie base.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE SCHEMA IF NOT EXISTS chf_interne;
CREATE SEQUENCE public.lignes_effacees_id_seq;
CREATE SEQUENCE public.paiements_numero_paiement_seq;

CREATE TABLE public.actes (id text NOT NULL, nom text NOT NULL, prix numeric(10,2) NOT NULL, sub text, categorie text DEFAULT 'acte'::text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.audit_log (id uuid DEFAULT gen_random_uuid() NOT NULL, action text NOT NULL, details jsonb DEFAULT '{}'::jsonb, effectue_par text, effectue_par_uid text, date timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.catalog (type text NOT NULL, items jsonb DEFAULT '[]'::jsonb NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.cloture_caisse (id text NOT NULL, date text, solde_ouverture numeric, comptant_remis numeric, fond_conserve numeric, justification text, statut text, cloturee_par text, date_cloture timestamp with time zone, cloturee_par_uid text);
CREATE TABLE public.compteurs (id text NOT NULL, derniernumero integer DEFAULT 0, updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.decrements_stock_appliques (local_id text NOT NULL, applique_le timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.demandes_exoneration (id uuid DEFAULT gen_random_uuid() NOT NULL, episode_id uuid, patient_nom text, montant_total numeric(12,2), pourcentage_demande numeric(5,2), montant_exonere numeric(12,2), demandeur text, demandeur_uid text, statut text DEFAULT 'en_attente'::text NOT NULL, reponse_par text, date_reponse timestamp with time zone, date_demande timestamp with time zone DEFAULT now() NOT NULL, motif text, fiche_snapshot jsonb);
CREATE TABLE public.depenses_caisse (id text DEFAULT (gen_random_uuid())::text NOT NULL, motif text NOT NULL, montant numeric(10,2) NOT NULL, date_demande timestamp with time zone DEFAULT now(), caissier_uid text, local_id text, demandeur text NOT NULL, demandeur_uid text NOT NULL, statut text DEFAULT 'en_attente'::text NOT NULL, caissier text, date_reponse timestamp with time zone);
CREATE TABLE public.dossiers (id uuid DEFAULT gen_random_uuid() NOT NULL, numero_dossier text NOT NULL, nom text NOT NULL, date_naissance date, telephone text, adresse text, date_creation timestamp with time zone DEFAULT now() NOT NULL, local_id text, poids numeric, conjoint text, sexe text, nom_origine text, modifie_le timestamp with time zone DEFAULT now() NOT NULL, mere_dossier_id uuid, anciens_noms jsonb DEFAULT '[]'::jsonb NOT NULL, fusionne_dans uuid, fusionne_le timestamp with time zone, fusionne_par text, fusion_details jsonb);
CREATE TABLE public.doublons_ignores (dossier_a uuid NOT NULL, dossier_b uuid NOT NULL, ignore_par text, ignore_le timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.episodes (id uuid DEFAULT gen_random_uuid() NOT NULL, dossier_id uuid NOT NULL, voie_entree text NOT NULL, service text, type_consultation text, type_patient text NOT NULL, ong_partenaire text, statut text DEFAULT 'ouvert'::text NOT NULL, est_hospitalisation boolean DEFAULT false NOT NULL, motif_fermeture text, numero_lot integer, mois_report text, verrouille_facture boolean DEFAULT false NOT NULL, date_suspension timestamp with time zone, en_attente_resultats boolean DEFAULT false NOT NULL, date_ouverture timestamp with time zone DEFAULT now() NOT NULL, date_fermeture timestamp with time zone, local_id text, lit text, supprime_le timestamp with time zone, mois_lot text, lot_verrouille boolean DEFAULT false NOT NULL, modifie_le timestamp with time zone DEFAULT now() NOT NULL, dossier_complet boolean DEFAULT false NOT NULL, modifie_par text, modifie_par_uid text, ong_partenaire_id text);
CREATE TABLE public.erreurs_client (id uuid DEFAULT gen_random_uuid() NOT NULL, empreinte text NOT NULL, message text NOT NULL, pile text, source text DEFAULT 'js'::text NOT NULL, onglet text, version_app text, premiere_le timestamp with time zone DEFAULT now() NOT NULL, derniere_le timestamp with time zone DEFAULT now() NOT NULL, nombre integer DEFAULT 1 NOT NULL, postes text[] DEFAULT '{}'::text[] NOT NULL, utilisateurs text[] DEFAULT '{}'::text[] NOT NULL, statut text DEFAULT 'nouveau'::text NOT NULL, traite_par text, traite_le timestamp with time zone);
CREATE TABLE public.fiches (id uuid DEFAULT gen_random_uuid() NOT NULL, episode_id uuid NOT NULL, numero_fiche bigint, local_id text, date_creation timestamp with time zone DEFAULT now() NOT NULL, cree_par text, probleme boolean DEFAULT false NOT NULL, note_probleme text, total_global numeric(12,2) DEFAULT 0 NOT NULL, breakdown jsonb DEFAULT '{}'::jsonb NOT NULL, mode_paiement text, raw_state jsonb DEFAULT '{}'::jsonb NOT NULL, cree_par_uid text, supprime_le timestamp with time zone, modifie_le timestamp with time zone DEFAULT now() NOT NULL, numero_fiche_avant bigint);
CREATE TABLE public.invitations (token text NOT NULL, role text NOT NULL, note text, cree_par_uid text, cree_par_email text, date_creation timestamp with time zone DEFAULT now() NOT NULL, date_expiration timestamp with time zone NOT NULL, revoque boolean DEFAULT false NOT NULL, utilise_le timestamp with time zone, utilise_par_uid text, utilise_par_email text);
CREATE TABLE public.lignes_effacees (id bigint DEFAULT nextval('lignes_effacees_id_seq'::regclass) NOT NULL, table_nom text NOT NULL, ligne_id uuid NOT NULL, episode_id uuid, efface_le timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.medicaments (id text NOT NULL, nom text NOT NULL, prix numeric(10,2) NOT NULL, quantite numeric(10,2) DEFAULT 0, seuilalerte numeric(10,2) DEFAULT 5, dateperemption date, categorie text DEFAULT 'pharmacie'::text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.migrations_appliquees (nom text NOT NULL, somme_controle text, applique_le timestamp with time zone DEFAULT now() NOT NULL, applique_par text, remarque text);
CREATE TABLE public.ong_partenaires (id text NOT NULL, nom text NOT NULL, date_ajout timestamp with time zone DEFAULT now(), ajoute_par text, prochain_numero integer DEFAULT 1, supprime_le timestamp with time zone, date_fin_contrat date);
CREATE TABLE public.paiements (id uuid DEFAULT gen_random_uuid() NOT NULL, numero_paiement bigint DEFAULT nextval('paiements_numero_paiement_seq'::regclass) NOT NULL, fiche_id uuid, episode_id uuid, local_id text, mode text NOT NULL, montant numeric(12,2) NOT NULL, date_paiement timestamp with time zone DEFAULT now() NOT NULL, details jsonb DEFAULT '{}'::jsonb, annule boolean DEFAULT false NOT NULL, annule_par text, annule_le timestamp with time zone, motif_annulation text, encaisse_par text, patient_nom text, solde_restant numeric, ong_partenaire text, exoneration jsonb, traite_par_uid text, type_patient text, annule_par_uid text, supprime_le timestamp with time zone, modifie_le timestamp with time zone DEFAULT now() NOT NULL, ong_partenaire_id text);
CREATE TABLE public.pieces_jointes (id uuid DEFAULT gen_random_uuid() NOT NULL, dossier_id uuid NOT NULL, storage_path text NOT NULL, nom_original text NOT NULL, type_document text, taille_octets bigint, ajoute_par text, ajoute_par_uid text, date_ajout timestamp with time zone DEFAULT now() NOT NULL, supprime_le timestamp with time zone);
CREATE TABLE public.postes_etat (poste_id text NOT NULL, uid text, utilisateur text, role text, premier_le timestamp with time zone DEFAULT now() NOT NULL, vu_le timestamp with time zone DEFAULT now() NOT NULL, version_app text, appareil text, onglet text, en_ligne boolean DEFAULT true NOT NULL, en_attente integer DEFAULT 0 NOT NULL, bloquees integer DEFAULT 0 NOT NULL, anciennete_file_s integer, derniere_sync_le timestamp with time zone, decalage_ms bigint, latence_ms integer, erreurs_recentes integer DEFAULT 0 NOT NULL);
CREATE TABLE public.requetes_idempotentes (cle text NOT NULL, methode text NOT NULL, chemin text NOT NULL, uid text NOT NULL, statut integer, reponse jsonb, cree_le timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.requisitions (id uuid DEFAULT gen_random_uuid() NOT NULL, service_demandeur text NOT NULL, lignes jsonb NOT NULL, demande_par text, demande_par_uid text, date_requisition timestamp with time zone DEFAULT now() NOT NULL, local_id text);
CREATE TABLE public.salaires_service (id text NOT NULL, montant_mensuel numeric DEFAULT 0);
CREATE TABLE public.transferts_service (id uuid DEFAULT gen_random_uuid() NOT NULL, episode_id uuid NOT NULL, ancien_service text, nouveau_service text NOT NULL, motif text, transfere_par text, transfere_par_uid text, date_transfert timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.users (id text NOT NULL, display_name text, role text, active boolean DEFAULT true NOT NULL, email text, date_expiration timestamp with time zone);

ALTER TABLE public.actes ADD CONSTRAINT actes_pkey PRIMARY KEY (id);
ALTER TABLE public.audit_log ADD CONSTRAINT audit_log_pkey PRIMARY KEY (id);
ALTER TABLE public.catalog ADD CONSTRAINT catalog_pkey PRIMARY KEY (type);
ALTER TABLE public.cloture_caisse ADD CONSTRAINT cloture_caisse_pkey PRIMARY KEY (id);
ALTER TABLE public.compteurs ADD CONSTRAINT compteurs_pkey PRIMARY KEY (id);
ALTER TABLE public.decrements_stock_appliques ADD CONSTRAINT decrements_stock_appliques_pkey PRIMARY KEY (local_id);
ALTER TABLE public.demandes_exoneration ADD CONSTRAINT demandes_exoneration_pkey PRIMARY KEY (id);
ALTER TABLE public.depenses_caisse ADD CONSTRAINT depenses_caisse_pkey PRIMARY KEY (id);
ALTER TABLE public.dossiers ADD CONSTRAINT dossiers_pkey PRIMARY KEY (id);
ALTER TABLE public.doublons_ignores ADD CONSTRAINT doublons_ignores_pkey PRIMARY KEY (dossier_a, dossier_b);
ALTER TABLE public.episodes ADD CONSTRAINT episodes_pkey PRIMARY KEY (id);
ALTER TABLE public.erreurs_client ADD CONSTRAINT erreurs_client_pkey PRIMARY KEY (id);
ALTER TABLE public.fiches ADD CONSTRAINT fiches_pkey PRIMARY KEY (id);
ALTER TABLE public.invitations ADD CONSTRAINT invitations_pkey PRIMARY KEY (token);
ALTER TABLE public.lignes_effacees ADD CONSTRAINT lignes_effacees_pkey PRIMARY KEY (id);
ALTER TABLE public.medicaments ADD CONSTRAINT medicaments_pkey PRIMARY KEY (id);
ALTER TABLE public.migrations_appliquees ADD CONSTRAINT migrations_appliquees_pkey PRIMARY KEY (nom);
ALTER TABLE public.ong_partenaires ADD CONSTRAINT ong_partenaires_pkey PRIMARY KEY (id);
ALTER TABLE public.paiements ADD CONSTRAINT paiements_pkey PRIMARY KEY (id);
ALTER TABLE public.pieces_jointes ADD CONSTRAINT pieces_jointes_pkey PRIMARY KEY (id);
ALTER TABLE public.postes_etat ADD CONSTRAINT postes_etat_pkey PRIMARY KEY (poste_id);
ALTER TABLE public.requetes_idempotentes ADD CONSTRAINT requetes_idempotentes_pkey PRIMARY KEY (cle);
ALTER TABLE public.requisitions ADD CONSTRAINT requisitions_pkey PRIMARY KEY (id);
ALTER TABLE public.salaires_service ADD CONSTRAINT salaires_service_pkey PRIMARY KEY (id);
ALTER TABLE public.transferts_service ADD CONSTRAINT transferts_service_pkey PRIMARY KEY (id);
ALTER TABLE public.users ADD CONSTRAINT users_pkey PRIMARY KEY (id);
ALTER TABLE public.depenses_caisse ADD CONSTRAINT depenses_caisse_local_id_unique UNIQUE (local_id);
ALTER TABLE public.dossiers ADD CONSTRAINT dossiers_numero_dossier_key UNIQUE (numero_dossier);
ALTER TABLE public.erreurs_client ADD CONSTRAINT erreurs_client_empreinte_key UNIQUE (empreinte);
ALTER TABLE public.fiches ADD CONSTRAINT fiches_episode_id_numero_fiche_key UNIQUE (episode_id, numero_fiche);
ALTER TABLE public.fiches ADD CONSTRAINT fiches_local_id_key UNIQUE (local_id);
ALTER TABLE public.paiements ADD CONSTRAINT paiements_local_id_key UNIQUE (local_id);
ALTER TABLE public.paiements ADD CONSTRAINT paiements_numero_paiement_key UNIQUE (numero_paiement);
ALTER TABLE public.demandes_exoneration ADD CONSTRAINT demandes_exoneration_statut_check CHECK ((statut = ANY (ARRAY['en_attente'::text, 'en_cours_de_traitement'::text, 'accepte'::text, 'refuse'::text])));
ALTER TABLE public.dossiers ADD CONSTRAINT dossiers_fusion_pas_soi CHECK (((fusionne_dans IS NULL) OR (fusionne_dans <> id)));
ALTER TABLE public.dossiers ADD CONSTRAINT dossiers_mere_pas_soi CHECK (((mere_dossier_id IS NULL) OR (mere_dossier_id <> id)));
ALTER TABLE public.dossiers ADD CONSTRAINT dossiers_sexe_valide CHECK (((sexe IS NULL) OR (sexe = ANY (ARRAY['M'::text, 'F'::text]))));
ALTER TABLE public.doublons_ignores ADD CONSTRAINT doublons_ignores_check CHECK ((dossier_a < dossier_b));
ALTER TABLE public.episodes ADD CONSTRAINT episodes_motif_fermeture_check CHECK ((motif_fermeture = ANY (ARRAY['exeat_normal'::text, 'exeat_sans_autorisation'::text, NULL::text])));
ALTER TABLE public.episodes ADD CONSTRAINT episodes_statut_check CHECK ((statut = ANY (ARRAY['ouvert'::text, 'ferme'::text])));
ALTER TABLE public.episodes ADD CONSTRAINT episodes_type_patient_check CHECK ((type_patient = ANY (ARRAY['prive'::text, 'partenaire'::text])));
ALTER TABLE public.episodes ADD CONSTRAINT episodes_voie_entree_check CHECK ((voie_entree = ANY (ARRAY['urgence'::text, 'consultation'::text, 'vente_comptoir'::text])));
ALTER TABLE public.erreurs_client ADD CONSTRAINT erreurs_client_source_check CHECK ((source = ANY (ARRAY['js'::text, 'promesse'::text, 'react'::text])));
ALTER TABLE public.erreurs_client ADD CONSTRAINT erreurs_client_statut_check CHECK ((statut = ANY (ARRAY['nouveau'::text, 'vu'::text, 'resolu'::text])));
ALTER TABLE public.paiements ADD CONSTRAINT paiement_rattache_a_quelque_chose CHECK (((fiche_id IS NOT NULL) OR (episode_id IS NOT NULL)));
ALTER TABLE public.paiements ADD CONSTRAINT paiements_mode_check CHECK ((mode = ANY (ARRAY['cash'::text, 'ong'::text, 'credit'::text, 'depot'::text, 'exoneration'::text, 'remboursement_credit'::text, 'remboursement_patient'::text, 'moncash'::text, 'virement'::text, 'cheque'::text])));
ALTER TABLE public.paiements ADD CONSTRAINT paiements_montant_borne CHECK (((montant >= (0)::numeric) AND (montant <= (100000000)::numeric)));
ALTER TABLE public.postes_etat ADD CONSTRAINT postes_etat_bloquees_check CHECK ((bloquees >= 0));
ALTER TABLE public.postes_etat ADD CONSTRAINT postes_etat_en_attente_check CHECK ((en_attente >= 0));
ALTER TABLE public.postes_etat ADD CONSTRAINT postes_etat_erreurs_recentes_check CHECK ((erreurs_recentes >= 0));
ALTER TABLE public.postes_etat ADD CONSTRAINT postes_etat_poste_id_check CHECK (((length(poste_id) >= 8) AND (length(poste_id) <= 64)));
ALTER TABLE public.users ADD CONSTRAINT users_role_check CHECK ((((char_length(role) >= 3) AND (char_length(role) <= 30)) AND (role ~ '^[abcdefghijklmnopqrstuvwxyz][abcdefghijklmnopqrstuvwxyz0123456789]*(_[abcdefghijklmnopqrstuvwxyz0123456789]+)*$'::text)));
ALTER TABLE public.demandes_exoneration ADD CONSTRAINT demandes_exoneration_episode_id_fkey FOREIGN KEY (episode_id) REFERENCES episodes(id) ON DELETE SET NULL;
ALTER TABLE public.dossiers ADD CONSTRAINT dossiers_fusionne_dans_fkey FOREIGN KEY (fusionne_dans) REFERENCES dossiers(id) ON DELETE SET NULL;
ALTER TABLE public.dossiers ADD CONSTRAINT dossiers_mere_dossier_id_fkey FOREIGN KEY (mere_dossier_id) REFERENCES dossiers(id) ON DELETE SET NULL;
ALTER TABLE public.doublons_ignores ADD CONSTRAINT doublons_ignores_dossier_a_fkey FOREIGN KEY (dossier_a) REFERENCES dossiers(id) ON DELETE CASCADE;
ALTER TABLE public.doublons_ignores ADD CONSTRAINT doublons_ignores_dossier_b_fkey FOREIGN KEY (dossier_b) REFERENCES dossiers(id) ON DELETE CASCADE;
ALTER TABLE public.episodes ADD CONSTRAINT episodes_dossier_id_fkey FOREIGN KEY (dossier_id) REFERENCES dossiers(id) ON DELETE CASCADE;
ALTER TABLE public.fiches ADD CONSTRAINT fiches_episode_id_fkey FOREIGN KEY (episode_id) REFERENCES episodes(id) ON DELETE CASCADE;
ALTER TABLE public.paiements ADD CONSTRAINT paiements_episode_id_fkey FOREIGN KEY (episode_id) REFERENCES episodes(id) ON DELETE CASCADE;
ALTER TABLE public.paiements ADD CONSTRAINT paiements_fiche_id_fkey FOREIGN KEY (fiche_id) REFERENCES fiches(id) ON DELETE CASCADE;
ALTER TABLE public.pieces_jointes ADD CONSTRAINT pieces_jointes_dossier_id_fkey FOREIGN KEY (dossier_id) REFERENCES dossiers(id) ON DELETE CASCADE;
ALTER TABLE public.transferts_service ADD CONSTRAINT transferts_service_episode_id_fkey FOREIGN KEY (episode_id) REFERENCES episodes(id) ON DELETE CASCADE;

CREATE UNIQUE INDEX catalog_type_unique ON public.catalog USING btree (type);
CREATE UNIQUE INDEX dossiers_local_id_unique ON public.dossiers USING btree (local_id) WHERE (local_id IS NOT NULL);
CREATE INDEX idx_decrements_stock_appliques_date ON public.decrements_stock_appliques USING btree (applique_le);
CREATE INDEX idx_dossiers_date_naissance ON public.dossiers USING btree (date_naissance);
CREATE INDEX idx_dossiers_fusionne_dans ON public.dossiers USING btree (fusionne_dans) WHERE (fusionne_dans IS NOT NULL);
CREATE INDEX idx_dossiers_mere ON public.dossiers USING btree (mere_dossier_id) WHERE (mere_dossier_id IS NOT NULL);
CREATE INDEX idx_dossiers_naissance_tel ON public.dossiers USING btree (date_naissance, telephone);
CREATE INDEX idx_dossiers_nom ON public.dossiers USING gin (to_tsvector('french'::regconfig, nom));
CREATE INDEX idx_dossiers_nom_origine_trgm ON public.dossiers USING gin (nom_origine gin_trgm_ops);
CREATE INDEX idx_dossiers_nom_trgm ON public.dossiers USING gin (nom gin_trgm_ops);
CREATE INDEX idx_dossiers_numero ON public.dossiers USING btree (numero_dossier);
CREATE UNIQUE INDEX episodes_local_id_unique ON public.episodes USING btree (local_id) WHERE (local_id IS NOT NULL);
CREATE INDEX idx_episodes_dossier_ouvert ON public.episodes USING btree (dossier_id) WHERE (statut = 'ouvert'::text);
CREATE INDEX idx_episodes_ong_partenaire_id ON public.episodes USING btree (ong_partenaire_id) WHERE (ong_partenaire_id IS NOT NULL);
CREATE INDEX idx_episodes_supprime_le ON public.episodes USING btree (supprime_le) WHERE (supprime_le IS NOT NULL);
CREATE INDEX idx_erreurs_client_derniere ON public.erreurs_client USING btree (derniere_le DESC);
CREATE INDEX idx_fiches_episode ON public.fiches USING btree (episode_id);
CREATE INDEX idx_fiches_supprime_le ON public.fiches USING btree (supprime_le) WHERE (supprime_le IS NOT NULL);
CREATE INDEX idx_invitations_date_creation ON public.invitations USING btree (date_creation DESC);
CREATE INDEX idx_ong_partenaires_supprime_le ON public.ong_partenaires USING btree (supprime_le) WHERE (supprime_le IS NOT NULL);
CREATE INDEX idx_paiements_episode ON public.paiements USING btree (episode_id);
CREATE INDEX idx_paiements_fiche ON public.paiements USING btree (fiche_id);
CREATE INDEX idx_paiements_ong_partenaire_id ON public.paiements USING btree (ong_partenaire_id) WHERE (ong_partenaire_id IS NOT NULL);
CREATE INDEX idx_paiements_supprime_le ON public.paiements USING btree (supprime_le) WHERE (supprime_le IS NOT NULL);
CREATE INDEX idx_pieces_jointes_dossier ON public.pieces_jointes USING btree (dossier_id);
CREATE INDEX idx_pieces_jointes_supprime_le ON public.pieces_jointes USING btree (supprime_le) WHERE (supprime_le IS NOT NULL);
CREATE INDEX idx_postes_etat_vu ON public.postes_etat USING btree (vu_le DESC);
CREATE INDEX idx_requetes_idempotentes_cree_le ON public.requetes_idempotentes USING btree (cree_le);
CREATE INDEX idx_requisitions_date ON public.requisitions USING btree (date_requisition);
CREATE UNIQUE INDEX idx_requisitions_local_id ON public.requisitions USING btree (local_id) WHERE (local_id IS NOT NULL);
CREATE INDEX idx_requisitions_service ON public.requisitions USING btree (service_demandeur);
CREATE INDEX idx_transferts_episode ON public.transferts_service USING btree (episode_id);
